const UI='0.2.1-beta2',RAW='https://raw.githubusercontent.com/huoguotiankong/source-core-8d7/main/',CDN='https://cdn.jsdelivr.net/gh/huoguotiankong/source-core-8d7@main/',ICON=RAW+'assets/reader-repo-icon.jpg';
function repo(p){const{source}=this;return String(source.get('repoLine')||'raw')==='cdn'?CDN+p:RAW+p}
function lineName(){const{source}=this;return String(source.get('repoLine')||'raw')==='cdn'?'jsDelivr':'GitHub Raw'}
function switchLine(){const{source,java}=this,n=String(source.get('repoLine')||'raw')==='raw'?'cdn':'raw';source.put('repoLine',n);java.longToast('已切换：'+(n==='cdn'?'jsDelivr':'GitHub Raw')+'\n刷新当前分类后生效')}
function q(p,k,v){return repo(p)+'?'+encodeURIComponent(k)+'='+encodeURIComponent(v)}
function qp(u,k,v){return String(u)+(String(u).includes('?')?'&':'?')+encodeURIComponent(k)+'='+encodeURIComponent(v)}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;')}
function param(u,k){let m=String(u||'').match(new RegExp('[?&]'+k+'=([^&#]*)'));return m?decodeURIComponent(m[1]):''}

