let bu=String(baseUrl||''),title='🌈 阅读书源仓库',summary='',badge=[],action='',extra='',item=param(bu,'item'),channel=param(bu,'channel'),topic=param(bu,'topic'),sch=param(bu,'sc8d7ch'),ver=param(bu,'sc8d7ver');
try{if(rssArticle&&rssArticle.title)title=String(rssArticle.title);if(rssArticle&&rssArticle.description)summary=String(rssArticle.description)}catch(e){}
if(bu.includes('/rss/data/home.json')){
 if(item==='overview'){title='🌈 阅读书源仓库';summary='统一浏览、测试和导入本项目发布的阅读书源。';badge=['Repository','UI '+UI];extra='<div class=\"card\"><b>设计原则</b><p>原生列表负责快速浏览，详情页负责版本、说明与导入操作。正式版与测试版严格分开。</p></div>'}
 else if(item==='line'){title='📡 仓库线路';summary='当前线路：'+lineName();badge=['Network'];extra='<div class=\"card\"><b>切换方式</b><p>返回订阅源设置页，点击“📡 切换仓库线路”，再刷新当前分类。GitHub Raw 为默认线路，jsDelivr 为备用。</p></div>'}
 else if(item==='policy'){title='⭐ Stable / 🧪 Beta';summary='同一书源的正式版和测试版保持同一个 bookSourceUrl，测试通过后直接升级覆盖，不制造重复源。';badge=['Release Policy'];extra='<div class=\"card\"><b>发布规则</b><p>新版本默认进入 Beta。只有真机确认正常或明确要求发布正式版后，才进入 Stable。</p></div>'}
 else if(item==='update'){title='🔄 更新仓库订阅源';summary='当前测试界面版本：'+UI;badge=['Beta'];let u=RAW+'rss/reader-source-repository-beta2.json';action='<a class=\"btn\" href=\"legado://import/rssSource?src='+u+'\">重新导入 Beta 2</a>'}
}else if(bu.includes('/rss/data/bundle.json')){
 let st=channel==='stable';title=st?'⭐ 全部正式版':'🧪 全部测试版';summary=st?'批量导入所有 Stable 书源。':'批量导入当前 Beta/Test 书源。';badge=[st?'Stable':'Beta'];let u=repo(st?'bundles/all-stable.json':'bundles/all-beta.json');action='<a class=\"btn\" href=\"legado://import/bookSource?src='+u+'\">打开批量导入</a>'
}else if(bu.includes('/rss/data/help.json')){
 if(topic==='update'){title='⬇️ 导入与更新';summary='GitHub 负责分发，书源导入阅读后完整保存在本地。';extra='<div class=\"card\"><b>更新关系</b><p>同一个书源 Stable/Beta 使用同一个唯一身份 URL，因此导入新版会识别为同一书源的更新。</p></div>'}
 else{title='📖 使用说明';summary='通过顶部分类浏览书源；点击书源进入详情并选择导入。';extra='<div class=\"card\"><b>分类</b><p>⭐ 正式版：已确认稳定。<br>🧪 测试版：待真机验证。<br>📦 批量导入：一次导入某个通道全部书源。</p></div>'}
}else if(bu.includes('/subscription/')){summary='当前通道暂未收录实际书源。';badge=[bu.includes('stable')?'Stable':'Beta']}
else{
 let clean=bu.split('?')[0];title=title||'书源详情';summary=summary||'书源详情';if(sch)badge.push(sch==='stable'?'Stable':'Beta');if(ver)badge.push('v'+ver);action='<a class=\"btn\" href=\"legado://import/bookSource?src='+clean+'\">导入 / 更新书源</a>'
}
let b=badge.map(x=>'<i>'+esc(x)+'</i>').join('');
